veil/integrations/_common.py:
"""Shared helpers for the Anthropic and OpenAI wrappers: masking/restoring
values inside arbitrary JSON-shaped message and tool-argument structures,
regardless of whether the SDK hands us a plain ``dict`` or a pydantic-style
model object.
"""

from __future__ import annotations

import inspect
import json
from collections import OrderedDict
from typing import Any

from veil.masker import Masker
from veil.restore import restore_json_text


def mask_value(value: Any, masker: Masker) -> Any:
    """Recursively mask every string found in a JSON-shaped value."""
    if isinstance(value, str):
        return masker.mask(value)
    if isinstance(value, list):
        return [mask_value(v, masker) for v in value]
    if isinstance(value, dict):
        return {k: mask_value(v, masker) for k, v in value.items()}
    return value


def restore_value(value: Any, masker: Masker, *, tolerant: bool = True) -> Any:
    """Recursively restore every string found in a JSON-shaped value."""
    if isinstance(value, str):
        return masker.restore(value, tolerant=tolerant)
    if isinstance(value, list):
        return [restore_value(v, masker, tolerant=tolerant) for v in value]
    if isinstance(value, dict):
        return {k: restore_value(v, masker, tolerant=tolerant) for k, v in value.items()}
    return value


def restore_arguments(arguments: str, masker: Masker) -> str:
    """Restore a complete tool-call ``arguments`` JSON string.

    Parsed, restored value by value and re-serialized, so the restore doesn't
    depend on how the model escaped the surrogate (``\\u27e8`` for ``⟨``).
    """
    try:
        parsed = json.loads(arguments)
    except ValueError:
        return restore_json_text(arguments, masker.vault)  # truncated or not JSON: best effort
    restored = restore_value(parsed, masker)
    return arguments if restored == parsed else json.dumps(restored, ensure_ascii=False)


def needs_await(method: Any) -> bool:
    """True when calling ``method`` returns a coroutine: a method of an SDK's async client.

    Both SDKs wrap their ``create`` methods in a plain decorator, so the coroutine
    function is only visible underneath it.
    """
    if method is None:
        return False
    try:
        method = inspect.unwrap(method)
    except ValueError:  # a cycle of __wrapped__: not something an SDK produces
        return False
    return inspect.iscoroutinefunction(method)


def model_copy_with(obj: Any, **updates: Any) -> Any:
    """Return a copy of ``obj`` with ``updates`` applied, whatever shape it is:
    a pydantic-style model (has ``model_copy``), a plain ``dict``, or a
    generic attribute-bearing object (e.g. ``types.SimpleNamespace``, as used
    by the fakes in this project's own tests, and often by other SDKs' test
    doubles too).
    """
    if hasattr(obj, "model_copy"):
        return obj.model_copy(update=updates)
    if isinstance(obj, dict):
        return {**obj, **updates}
    for key, val in updates.items():
        setattr(obj, key, val)
    return obj


def get_field(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _plain(value: Any) -> Any:
    """A JSON-comparable form of an SDK object, dict, or scalar, with ``None`` fields dropped (an SDK
    model dumps absent optionals as ``None``; the same block rebuilt as a dict usually omits them)."""
    if hasattr(value, "model_dump"):
        value = value.model_dump(mode="json")
    elif (
        not isinstance(value, (dict, list, str, int, float, bool))
        and value is not None
        and hasattr(value, "__dict__")
    ):
        value = vars(value)
    if isinstance(value, dict):
        return {k: _plain(v) for k, v in value.items() if v is not None}
    if isinstance(value, list):
        return [_plain(v) for v in value]
    return value


def fingerprint(value: Any) -> str:
    return json.dumps(_plain(value), sort_keys=True, ensure_ascii=False, default=str)


class ReplayCache:
    """Maps what veil handed the application back to exactly what the model produced.

    An application keeps the conversation it saw: assistant turns with real values restored. On the
    next request those turns go back to the API, and re-masking them only approximates the original -
    a value the model wrote itself that happens to look like PII gets a fresh surrogate, a tolerant
    restore of a mangled surrogate doesn't round-trip. Any difference is an edit to an earlier turn:
    it restarts the prompt cache from that point, and on current Claude models it invalidates the
    signature of every later thinking block (a 400 on accounts that enforce the check). Replaying the
    remembered original instead keeps the history byte-identical to what the provider returned.
    """

    def __init__(self, max_entries: int = 10_000) -> None:
        self._entries: OrderedDict[str, Any] = OrderedDict()
        self._max_entries = max_entries

    def remember(self, restored: Any, original: Any) -> None:
        key = fingerprint(restored)
        self._entries[key] = original
        self._entries.move_to_end(key)
        while len(self._entries) > self._max_entries:
            self._entries.popitem(last=False)

    def original_for(self, value: Any) -> Any | None:
        return self._entries.get(fingerprint(value))

    def __len__(self) -> int:
        return len(self._entries)

veil/integrations/anthropic.py:
"""A thin wrapper around the Anthropic Python SDK that masks outgoing
messages and restores PII in the response, streaming included.

Requires the ``anthropic`` extra (``pip install "veil-pii[anthropic]"``).
This module only touches the SDK's public, documented surface
(``client.messages.create`` / ``client.messages.stream``, the
``MessageStream`` helper's events, ``text_stream`` and
``get_final_message()``). It makes no live calls and this repo has no API key;
it is tested two ways. ``tests/test_integration_anthropic.py`` uses fakes
shaped like the SDK. ``tests/test_sdk_anthropic.py`` runs the real SDK, sync
and async, over a mocked HTTP transport that answers in the API's wire format,
so the events veil sees there are the ones the SDK really builds.

**What gets masked:** every text block, tool-result content string and
``tool_use`` input value in ``messages``, and every text block in ``system``
(both the plain-string and the list-of-blocks forms). Images and other binary
content pass through untouched — veil only understands text. Thinking blocks
pass through untouched too: they carry a signature over their exact content.

**What gets restored:** every text block and tool_use ``input`` value in
the response, including from a token stream (via
:class:`veil.restore.Restorer`, so a surrogate split across chunks is still
caught).

**Streaming.** Three ways to stream, all restored:
``AnthropicVeil.stream(...).text_stream``; iterating the stream's events; and
``create(..., stream=True)``, the raw event iterator. In the events, text
deltas and tool-input JSON fragments go through a restorer per content block.
The SDK's own helper events are restored with them: ``text`` (the delta and the
text so far), ``input_json`` (the fragment and the input so far), and the
snapshots on ``content_block_stop`` and ``message_stop``. Text held back
because it might begin a surrogate is released before its block's
``content_block_stop``, as one more delta event (a copy of the block's last
one, so the SDK type is kept).

**Async.** :class:`AsyncAnthropicVeil` is the same wrapper for
``anthropic.AsyncAnthropic``. Each wrapper refuses the other kind of client:
handed an async client, the sync wrapper would mask the request and return a
coroutine it cannot restore.

**History replay:** an assistant turn veil restored comes back on the next
request with real values in it (in its text, and in the ``tool_use`` input
the application just executed). :class:`AnthropicVeil` remembers the exact
blocks the model produced and sends those instead, so the history the API
sees never changes between requests - see :class:`ReplayCache` for why that
matters for prompt caching and thinking-block signatures. A block veil never
restored (or one the application edited) is masked like any other.
"""

from __future__ import annotations

from collections.abc import AsyncIterator, Generator, Iterator
from dataclasses import dataclass, field
from typing import Any

from veil.integrations._common import (
    ReplayCache,
    get_field,
    mask_value,
    model_copy_with,
    needs_await,
    restore_value,
)
from veil.masker import Masker
from veil.restore import Restorer


def mask_content(content: Any, masker: Masker, replay: ReplayCache | None = None) -> Any:
    """Mask a message's ``content`` field (a string, or a list of blocks).

    With ``replay``, anything veil restored earlier is swapped back for the
    exact original instead of being re-masked.
    """
    if replay is not None and isinstance(content, str | list):
        original = replay.original_for(content)
        if original is not None:
            return original
    if isinstance(content, str):
        return masker.mask(content)
    if isinstance(content, list):
        return [_mask_block(b, masker, replay) for b in content]
    return content


def _mask_block(block: Any, masker: Masker, replay: ReplayCache | None = None) -> Any:
    if replay is not None:
        original = replay.original_for(block)
        if original is not None:
            return original
    block_type = get_field(block, "type")
    if block_type == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.mask(text))
    elif block_type == "tool_result":
        result_content = get_field(block, "content")
        if result_content is not None:
            return model_copy_with(block, content=mask_content(result_content, masker))
    elif block_type == "tool_use":
        # A prior assistant turn's tool call, restored for the application to execute: without
        # this, its real arguments would go straight back to the API in the next request.
        tool_input = get_field(block, "input")
        if tool_input is not None:
            return model_copy_with(block, input=mask_value(tool_input, masker))
    return block


def mask_messages(
    messages: list[Any], masker: Masker, replay: ReplayCache | None = None
) -> list[Any]:
    return [
        model_copy_with(m, content=mask_content(get_field(m, "content"), masker, replay))
        for m in messages
    ]


def mask_system(system: Any, masker: Masker) -> Any:
    if isinstance(system, str):
        return masker.mask(system)
    if isinstance(system, list):
        return [_mask_block(b, masker) for b in system]
    return system


def _restore_block(block: Any, masker: Masker) -> Any:
    block_type = get_field(block, "type")
    if block_type == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.restore(text))
    elif block_type == "tool_use":
        tool_input = get_field(block, "input")
        if tool_input is not None:
            return model_copy_with(block, input=restore_value(tool_input, masker))
    return block


def restore_message(message: Any, masker: Masker, replay: ReplayCache | None = None) -> Any:
    """Restore a full (non-streamed) response message's content blocks.

    With ``replay``, every restored block (and the restored content list, and
    each text block's restored text on its own - applications store any of
    the three as history) is remembered against the original.
    """
    content = get_field(message, "content")
    if not isinstance(content, list):
        return message
    restored = [_restore_block(b, masker) for b in content]
    if replay is not None:
        replay.remember(restored, content)
        for new, old in zip(restored, content, strict=True):
            replay.remember(new, old)
            if get_field(new, "type") == "text" and isinstance(get_field(new, "text"), str):
                replay.remember(get_field(new, "text"), get_field(old, "text"))
    return model_copy_with(message, content=restored)


@dataclass
class _Held:
    """One streamed content block: its restorer, the last delta event seen for it (the
    template for releasing held-back text) and what has been released so far."""

    restorer: Restorer
    is_text: bool
    last_delta: Any = None
    last_helper: Any = None  # the SDK's `text` / `input_json` event that followed that delta
    restored: str = ""


class EventRestorer:
    """Restores the events of one message stream, one at a time.

    It does no I/O: the sync and the async stream wrappers both feed it what the SDK
    yields and pass on what it returns. An event comes back as one event, or as several
    when held-back text has to be released ahead of it.
    """

    def __init__(self, masker: Masker, replay: ReplayCache | None = None) -> None:
        self._masker = masker
        self._replay = replay
        self._held: dict[int, _Held] = {}
        # The block and restored text of the delta just seen: the SDK follows a raw delta
        # with a helper event (`text`, `input_json`) describing the same delta.
        self._current: int | None = None
        self._piece = ""

    def _feed_delta(self, event: Any, delta: Any, field_name: str) -> Any:
        index = get_field(event, "index", 0)
        held = self._held.get(index)
        if held is None:
            is_text = field_name == "text"
            held = _Held(Restorer(self._masker.vault, json_string=not is_text), is_text)
            self._held[index] = held
        piece = held.restorer.feed(get_field(delta, field_name, "") or "")
        held.last_delta = event
        held.restored += piece
        self._current, self._piece = index, piece
        return model_copy_with(event, delta=model_copy_with(delta, **{field_name: piece}))

    def _release(self, index: int) -> list[Any]:
        """The text still held back for a block, as one more delta event (and one more
        helper event, when the stream has them)."""
        held = self._held.pop(index, None)
        if held is None:
            return []
        tail = held.restorer.flush()
        if not tail or held.last_delta is None:
            return []
        held.restored += tail
        field_name = "text" if held.is_text else "partial_json"
        delta = model_copy_with(get_field(held.last_delta, "delta"), **{field_name: tail})
        out = [model_copy_with(held.last_delta, delta=delta)]
        if held.last_helper is not None:
            if held.is_text:
                out.append(model_copy_with(held.last_helper, text=tail, snapshot=held.restored))
            else:
                out.append(model_copy_with(held.last_helper, partial_json=tail))
        return out

    def feed(self, event: Any) -> list[Any]:
        event_type = get_field(event, "type")
        if event_type == "content_block_delta":
            delta = get_field(event, "delta")
            delta_type = get_field(delta, "type")
            if delta_type == "text_delta":
                return [self._feed_delta(event, delta, "text")]
            if delta_type == "input_json_delta":
                return [self._feed_delta(event, delta, "partial_json")]
            return [event]  # thinking, signature and citation deltas pass through
        if event_type in ("text", "input_json"):
            held = self._held.get(self._current) if self._current is not None else None
            if held is None or held.is_text != (event_type == "text"):
                return [event]
            held.last_helper = event
            if held.is_text:
                return [model_copy_with(event, text=self._piece, snapshot=held.restored)]
            snapshot = restore_value(get_field(event, "snapshot"), self._masker)
            return [model_copy_with(event, partial_json=self._piece, snapshot=snapshot)]
        if event_type == "content_block_stop":
            out = self._release(get_field(event, "index", 0))
            block = get_field(event, "content_block")
            if block is not None:
                event = model_copy_with(event, content_block=_restore_block(block, self._masker))
            return [*out, event]
        if event_type == "message_stop":
            out = self.finish()
            message = get_field(event, "message")
            if message is not None:
                restored = restore_message(message, self._masker, self._replay)
                event = model_copy_with(event, message=restored)
            return [*out, event]
        return [event]

    def finish(self) -> list[Any]:
        """Release everything still held back: the stream ended, or was cut off."""
        out: list[Any] = []
        for index in list(self._held):
            out.extend(self._release(index))
        return out


class _Delegating:
    """Hands anything veil does not wrap (``close()``, ``response``, ``request_id``, ...)
    to the SDK object underneath."""

    raw: Any

    def _target(self) -> Any:
        return self.raw

    def __getattr__(self, name: str) -> Any:
        if name.startswith("_") or name == "raw":
            raise AttributeError(name)
        return getattr(self._target(), name)


@dataclass
class VeilEventStream(_Delegating):
    """The raw event iterator of ``client.messages.create(..., stream=True)``, restored."""

    raw: Any
    masker: Masker
    replay: ReplayCache | None = None

    def __enter__(self) -> VeilEventStream:
        if hasattr(self.raw, "__enter__"):
            self.raw.__enter__()
        return self

    def __exit__(self, *exc_info: object) -> Any:
        if hasattr(self.raw, "__exit__"):
            return self.raw.__exit__(*exc_info)
        return None

    def __iter__(self) -> Iterator[Any]:
        events = EventRestorer(self.masker, self.replay)
        for event in self.raw:
            yield from events.feed(event)
        yield from events.finish()


@dataclass
class VeilMessageStream(_Delegating):
    """Wraps the Anthropic SDK's ``MessageStream`` (the object returned by
    ``client.messages.stream(...)``) so text and events arrive already restored.
    """

    raw: Any  # the object returned by client.messages.stream(...) (a context manager)
    masker: Masker
    replay: ReplayCache | None = None
    _restorer: Restorer = field(init=False)
    _entered: Any = field(default=None, init=False)

    def __post_init__(self) -> None:
        self._restorer = Restorer(self.masker.vault)

    def _target(self) -> Any:
        return self._entered if self._entered is not None else self.raw

    def __enter__(self) -> VeilMessageStream:
        self._entered = self.raw.__enter__()
        return self

    def __exit__(self, *exc_info: object) -> Any:
        return self.raw.__exit__(*exc_info)

    @property
    def text_stream(self) -> Generator[str, None, None]:
        for text in self._target().text_stream:
            restored = self._restorer.feed(text)
            if restored:
                yield restored
        tail = self._restorer.flush()
        if tail:
            yield tail

    def __iter__(self) -> Iterator[Any]:
        """Yield the SDK's events, restored (see :class:`EventRestorer`)."""
        events = EventRestorer(self.masker, self.replay)
        for event in self._target():
            yield from events.feed(event)
        yield from events.finish()

    def get_final_message(self) -> Any:
        message = self._target().get_final_message()
        return restore_message(message, self.masker, self.replay)

    def get_final_text(self) -> str:
        return self.masker.restore(self._target().get_final_text())

    @property
    def current_message_snapshot(self) -> Any:
        return restore_message(self._target().current_message_snapshot, self.masker)


@dataclass
class AsyncVeilEventStream(_Delegating):
    """The raw event stream of ``await client.messages.create(..., stream=True)`` on an
    async client, restored."""

    raw: Any
    masker: Masker
    replay: ReplayCache | None = None

    async def __aenter__(self) -> AsyncVeilEventStream:
        if hasattr(self.raw, "__aenter__"):
            await self.raw.__aenter__()
        return self

    async def __aexit__(self, *exc_info: object) -> Any:
        if hasattr(self.raw, "__aexit__"):
            return await self.raw.__aexit__(*exc_info)
        return None

    async def __aiter__(self) -> AsyncIterator[Any]:
        events = EventRestorer(self.masker, self.replay)
        async for event in self.raw:
            for restored in events.feed(event):
                yield restored
        for restored in events.finish():
            yield restored


@dataclass
class AsyncVeilMessageStream(_Delegating):
    """Wraps the SDK's ``AsyncMessageStream`` (``async with client.messages.stream(...)``)."""

    raw: Any
    masker: Masker
    replay: ReplayCache | None = None
    _restorer: Restorer = field(init=False)
    _entered: Any = field(default=None, init=False)

    def __post_init__(self) -> None:
        self._restorer = Restorer(self.masker.vault)

    def _target(self) -> Any:
        return self._entered if self._entered is not None else self.raw

    async def __aenter__(self) -> AsyncVeilMessageStream:
        self._entered = await self.raw.__aenter__()
        return self

    async def __aexit__(self, *exc_info: object) -> Any:
        return await self.raw.__aexit__(*exc_info)

    @property
    def text_stream(self) -> AsyncIterator[str]:
        async def restored_text() -> AsyncIterator[str]:
            async for text in self._target().text_stream:
                restored = self._restorer.feed(text)
                if restored:
                    yield restored
            tail = self._restorer.flush()
            if tail:
                yield tail

        return restored_text()

    async def __aiter__(self) -> AsyncIterator[Any]:
        events = EventRestorer(self.masker, self.replay)
        async for event in self._target():
            for restored in events.feed(event):
                yield restored
        for restored in events.finish():
            yield restored

    async def get_final_message(self) -> Any:
        message = await self._target().get_final_message()
        return restore_message(message, self.masker, self.replay)

    async def get_final_text(self) -> str:
        return self.masker.restore(await self._target().get_final_text())

    @property
    def current_message_snapshot(self) -> Any:
        return restore_message(self._target().current_message_snapshot, self.masker)


def _is_async_client(client: Any) -> bool:
    """True for a client whose ``messages.create`` has to be awaited."""
    return needs_await(getattr(getattr(client, "messages", None), "create", None))


def _masked_call(
    masker: Masker, replay: ReplayCache, messages: list[Any], system: Any, kwargs: dict[str, Any]
) -> dict[str, Any]:
    call_kwargs: dict[str, Any] = dict(kwargs)
    call_kwargs["messages"] = mask_messages(messages, masker, replay)
    if system is not None:
        call_kwargs["system"] = mask_system(system, masker)
    return call_kwargs


@dataclass
class AnthropicVeil:
    """Mask-and-restore wrapper around an ``anthropic.Anthropic`` client.

    Example::

        from anthropic import Anthropic
        from veil.integrations.anthropic import AnthropicVeil

        veil_client = AnthropicVeil(Anthropic())
        response = veil_client.create(
            model="claude-opus-5-5",
            max_tokens=1024,
            messages=[{"role": "user", "content": "Email alice@example.com"}],
        )
        # response.content[0].text has the real address restored, but the
        # model itself only ever saw a surrogate.
    """

    client: Any
    masker: Masker = field(default_factory=Masker)
    replay: ReplayCache = field(default_factory=ReplayCache)

    def __post_init__(self) -> None:
        if _is_async_client(self.client):
            raise TypeError(
                "AnthropicVeil wraps a synchronous client (anthropic.Anthropic); "
                "use AsyncAnthropicVeil for anthropic.AsyncAnthropic"
            )

    def create(self, *, messages: list[Any], system: Any = None, **kwargs: Any) -> Any:
        """``client.messages.create``: a restored message, or with ``stream=True`` a
        :class:`VeilEventStream` of restored events."""
        call_kwargs = _masked_call(self.masker, self.replay, messages, system, kwargs)
        response = self.client.messages.create(**call_kwargs)
        if call_kwargs.get("stream"):
            return VeilEventStream(response, self.masker, self.replay)
        return restore_message(response, self.masker, self.replay)

    def stream(
        self, *, messages: list[Any], system: Any = None, **kwargs: Any
    ) -> VeilMessageStream:
        call_kwargs = _masked_call(self.masker, self.replay, messages, system, kwargs)
        raw_stream = self.client.messages.stream(**call_kwargs)
        return VeilMessageStream(raw_stream, self.masker, self.replay)


@dataclass
class AsyncAnthropicVeil:
    """Mask-and-restore wrapper around an ``anthropic.AsyncAnthropic`` client.

    Example::

        from anthropic import AsyncAnthropic
        from veil.integrations.anthropic import AsyncAnthropicVeil

        veil_client = AsyncAnthropicVeil(AsyncAnthropic())
        response = await veil_client.create(model=..., max_tokens=1024, messages=[...])

        async with veil_client.stream(model=..., max_tokens=1024, messages=[...]) as stream:
            async for text in stream.text_stream:
                print(text, end="")
    """

    client: Any
    masker: Masker = field(default_factory=Masker)
    replay: ReplayCache = field(default_factory=ReplayCache)

    def __post_init__(self) -> None:
        if not _is_async_client(self.client):
            raise TypeError(
                "AsyncAnthropicVeil wraps an asynchronous client (anthropic.AsyncAnthropic); "
                "use AnthropicVeil for anthropic.Anthropic"
            )

    async def create(self, *, messages: list[Any], system: Any = None, **kwargs: Any) -> Any:
        """``await client.messages.create``: a restored message, or with ``stream=True``
        an :class:`AsyncVeilEventStream` of restored events."""
        call_kwargs = _masked_call(self.masker, self.replay, messages, system, kwargs)
        response = await self.client.messages.create(**call_kwargs)
        if call_kwargs.get("stream"):
            return AsyncVeilEventStream(response, self.masker, self.replay)
        return restore_message(response, self.masker, self.replay)

    def stream(
        self, *, messages: list[Any], system: Any = None, **kwargs: Any
    ) -> AsyncVeilMessageStream:
        call_kwargs = _masked_call(self.masker, self.replay, messages, system, kwargs)
        raw_stream = self.client.messages.stream(**call_kwargs)
        return AsyncVeilMessageStream(raw_stream, self.masker, self.replay)

veil/integrations/openai.py:
"""A thin wrapper around the OpenAI Python SDK that masks outgoing messages
and restores PII in the response, streaming included.

Requires the ``openai`` extra (``pip install "veil-pii[openai]"``). Built
against the documented shape of ``client.chat.completions.create(...,
stream=True)`` — a message list of role/content dicts, and a stream of
``ChatCompletionChunk``-shaped objects with ``choices[].delta.content`` and
``choices[].delta.tool_calls[].function.arguments`` (a fragment of a JSON
*string*, unlike Anthropic's already-structured ``tool_use.input``). This
module makes no live API calls. ``tests/test_integration_openai.py`` tests it
against fakes; ``tests/test_sdk_openai.py`` runs the real SDK, sync and async,
over a mocked HTTP transport that answers in the API's wire format.

**Streaming.** ``OpenAIVeil.stream(...)`` and ``create(..., stream=True)`` both
return an :class:`OpenAIVeilStream`. Each choice has its own restorers (for
its content, its refusal, and each of its tool calls), since ``n > 1`` choices
arrive interleaved. Text held back because it might begin a surrogate is
released in the chunk that carries the choice's ``finish_reason``, so nothing
arrives after a choice has finished.

**Async.** :class:`AsyncOpenAIVeil` is the same wrapper for
``openai.AsyncOpenAI``; each refuses the other kind of client.

**Tool-call arguments are a JSON string.** In a complete response they are
parsed, restored value by value, and re-serialized, so the restore doesn't
depend on how the model escaped the surrogate (a model may write ``⟨`` as
``\\u27e8``). Mid-stream a surrogate can straddle a ``{``/``"``/``,``
boundary, so the fragments go through a :class:`veil.restore.Restorer` in
JSON-string mode instead - one per tool-call index, since parallel tool
calls interleave their fragments by index - which also recognizes the
escaped form and writes originals JSON-escaped.

**History replay:** an assistant message veil restored is swapped back for
the exact message the model produced when the application resends it, so
real values never return to the API and the resent history stays
byte-identical (see :class:`veil.integrations._common.ReplayCache`).
"""

from __future__ import annotations

from collections.abc import AsyncIterator, Iterator
from dataclasses import dataclass, field
from typing import Any

from veil.integrations import openai_responses
from veil.integrations._common import (
    ReplayCache,
    get_field,
    model_copy_with,
    needs_await,
    restore_arguments,
)
from veil.masker import Masker
from veil.restore import Restorer

__all__ = [
    "AsyncOpenAIVeil",
    "AsyncOpenAIVeilStream",
    "ChunkRestorer",
    "OpenAIVeil",
    "OpenAIVeilStream",
    "mask_content",
    "mask_messages",
    "restore_arguments",
    "restore_response",
]


def mask_content(content: Any, masker: Masker) -> Any:
    if isinstance(content, str):
        return masker.mask(content)
    if isinstance(content, list):
        return [_mask_content_block(b, masker) for b in content]
    return content


def _mask_content_block(block: Any, masker: Masker) -> Any:
    if get_field(block, "type") == "text":
        text = get_field(block, "text")
        if isinstance(text, str):
            return model_copy_with(block, text=masker.mask(text))
    return block


def _mask_tool_calls(tool_calls: Any, masker: Masker) -> Any:
    if not tool_calls:
        return tool_calls
    out = []
    for call in tool_calls:
        fn = get_field(call, "function")
        if fn is not None:
            args = get_field(fn, "arguments")
            if isinstance(args, str):
                fn = model_copy_with(fn, arguments=masker.mask(args))
            call = model_copy_with(call, function=fn)
        out.append(call)
    return out


def mask_messages(
    messages: list[Any], masker: Masker, replay: ReplayCache | None = None
) -> list[Any]:
    """Mask ``content`` on every message (system/user/assistant/tool), and
    ``tool_calls[].function.arguments`` on any prior assistant turns being
    resent as history — those may contain real values a previous
    :meth:`veil.masker.Masker.restore` call put back; re-masking maps them
    to the *same* surrogate already in the vault rather than a new one.
    With ``replay``, a message veil restored is replaced by the original.
    """
    out = []
    for message in messages:
        if replay is not None and get_field(message, "role") == "assistant":
            original = replay.original_for(message)
            if original is not None:
                out.append(original)
                continue
        content = get_field(message, "content")
        updates: dict[str, Any] = {}
        if content is not None:
            updates["content"] = mask_content(content, masker)
        tool_calls = get_field(message, "tool_calls")
        if tool_calls:
            updates["tool_calls"] = _mask_tool_calls(tool_calls, masker)
        out.append(model_copy_with(message, **updates) if updates else message)
    return out


def restore_response(response: Any, masker: Masker, replay: ReplayCache | None = None) -> Any:
    """Restore a full (non-streamed) ``ChatCompletion`` response."""
    choices = get_field(response, "choices") or []
    return model_copy_with(response, choices=[_restore_choice(c, masker, replay) for c in choices])


def _restore_choice(choice: Any, masker: Masker, replay: ReplayCache | None = None) -> Any:
    message = get_field(choice, "message")
    if message is None:
        return choice
    updates: dict[str, Any] = {}
    content = get_field(message, "content")
    if isinstance(content, str):
        updates["content"] = masker.restore(content)
    tool_calls = get_field(message, "tool_calls")
    if tool_calls:
        new_calls = []
        for call in tool_calls:
            fn = get_field(call, "function")
            if fn is not None:
                args = get_field(fn, "arguments")
                if isinstance(args, str):
                    fn = model_copy_with(fn, arguments=restore_arguments(args, masker))
                call = model_copy_with(call, function=fn)
            new_calls.append(call)
        updates["tool_calls"] = new_calls
    if not updates:
        return choice
    restored = model_copy_with(message, **updates)
    if replay is not None:
        replay.remember(restored, message)
    return model_copy_with(choice, message=restored)


@dataclass
class _Held:
    """One streamed string (a choice's content or refusal, a tool call's arguments): its
    restorer, and the chunk and choice (and tool-call delta) that last carried it, which are
    the template for releasing held-back text if the stream is cut off."""

    restorer: Restorer
    chunk: Any = None
    choice: Any = None
    call: Any = None


class ChunkRestorer:
    """Restores the chunks of one Chat Completions stream, one at a time. No I/O: the sync
    and the async stream wrappers both drive it."""

    def __init__(self, masker: Masker) -> None:
        self._masker = masker
        # Keyed by choice index: n > 1 choices arrive interleaved, and text fed to one
        # restorer from two of them would be stitched together across choices.
        self._text: dict[tuple[str, int], _Held] = {}
        self._tools: dict[tuple[int, int], _Held] = {}

    def _held_text(self, kind: str, index: int) -> _Held:
        key = (kind, index)
        if key not in self._text:
            self._text[key] = _Held(Restorer(self._masker.vault))
        return self._text[key]

    def feed(self, chunk: Any) -> list[Any]:
        choices = get_field(chunk, "choices") or []
        if not choices:
            return [chunk]  # e.g. the usage-only chunk of stream_options.include_usage
        restored = [self._restore_choice(chunk, choice) for choice in choices]
        return [model_copy_with(chunk, choices=restored)]

    def _restore_choice(self, chunk: Any, choice: Any) -> Any:
        delta = get_field(choice, "delta")
        if delta is None:
            return choice
        index = get_field(choice, "index", 0)
        finished = get_field(choice, "finish_reason") is not None
        updates: dict[str, Any] = {}
        for kind in ("content", "refusal"):
            value = get_field(delta, kind)
            piece = ""
            if isinstance(value, str):
                held = self._held_text(kind, index)
                held.chunk, held.choice = chunk, choice
                piece = held.restorer.feed(value)
                updates[kind] = piece
            if finished and (kind, index) in self._text:
                # The choice is done: what was held back for it belongs in this chunk.
                tail = self._text.pop((kind, index)).restorer.flush()
                if tail:
                    updates[kind] = piece + tail
        tool_calls = get_field(delta, "tool_calls")
        calls = [self._restore_tool_call(chunk, choice, index, c) for c in tool_calls or []]
        if finished:
            calls.extend(self._release_tools(index))
        if calls:
            updates["tool_calls"] = calls
        if not updates:
            return choice
        return model_copy_with(choice, delta=model_copy_with(delta, **updates))

    def _restore_tool_call(self, chunk: Any, choice: Any, index: int, call: Any) -> Any:
        fn = get_field(call, "function")
        if fn is None:
            return call
        args = get_field(fn, "arguments")
        if not isinstance(args, str):
            return call
        key = (index, get_field(call, "index", 0))
        if key not in self._tools:
            self._tools[key] = _Held(Restorer(self._masker.vault, json_string=True))
        held = self._tools[key]
        held.chunk, held.choice, held.call = chunk, choice, call
        return model_copy_with(
            call, function=model_copy_with(fn, arguments=held.restorer.feed(args))
        )

    def _release_tools(self, index: int) -> list[Any]:
        """Tool-call deltas carrying what is still held back for a choice's tool calls."""
        out = []
        for key in [k for k in self._tools if k[0] == index]:
            held = self._tools.pop(key)
            tail = held.restorer.flush()
            if tail and held.call is not None:
                fn = model_copy_with(get_field(held.call, "function"), arguments=tail)
                out.append(model_copy_with(held.call, function=fn))
        return out

    def finish(self) -> list[Any]:
        """After the stream ends: chunks for text still held back for choices that never
        got a ``finish_reason`` (a stream cut off). Each is a copy of the last chunk that
        carried that string (same SDK type, so ``chunk.choices[0].delta`` keeps working),
        holding only that choice and only the held-back text."""
        out = []
        for (kind, _), held in list(self._text.items()):
            tail = held.restorer.flush()
            if tail and held.chunk is not None:
                other = "refusal" if kind == "content" else "content"
                updates = {kind: tail, other: None, "tool_calls": None}
                out.append(_with_delta(held.chunk, held.choice, **updates))
        self._text.clear()
        for held in list(self._tools.values()):
            tail = held.restorer.flush()
            if tail and held.call is not None:
                fn = model_copy_with(get_field(held.call, "function"), arguments=tail)
                call = model_copy_with(held.call, function=fn)
                out.append(_with_delta(held.chunk, held.choice, content=None, tool_calls=[call]))
        self._tools.clear()
        return out


def _with_delta(chunk: Any, choice: Any, **delta_updates: Any) -> Any:
    """``chunk`` holding only ``choice``, its delta replaced by ``delta_updates``."""
    delta = get_field(choice, "delta")
    if not isinstance(delta, dict) and not hasattr(delta, "refusal"):
        delta_updates.pop("refusal", None)  # a test double without the field: don't add it
    delta = model_copy_with(delta, **delta_updates)
    return model_copy_with(chunk, choices=[model_copy_with(choice, delta=delta)])


class _Delegating:
    """Hands anything veil does not wrap (``close()``, ``response``, ...) to the SDK's
    stream underneath."""

    raw: Any

    def __getattr__(self, name: str) -> Any:
        if name.startswith("_") or name == "raw":
            raise AttributeError(name)
        return getattr(self.raw, name)


@dataclass
class OpenAIVeilStream(_Delegating):
    """Wraps the raw chunk iterator from ``client.chat.completions.create(
    ..., stream=True)`` so text and tool-call arguments arrive restored.
    """

    raw: Any
    masker: Masker

    def __enter__(self) -> OpenAIVeilStream:
        if hasattr(self.raw, "__enter__"):
            self.raw.__enter__()
        return self

    def __exit__(self, *exc_info: object) -> Any:
        if hasattr(self.raw, "__exit__"):
            return self.raw.__exit__(*exc_info)
        return None

    def __iter__(self) -> Iterator[Any]:
        chunks = ChunkRestorer(self.masker)
        for chunk in self.raw:
            yield from chunks.feed(chunk)
        yield from chunks.finish()


@dataclass
class AsyncOpenAIVeilStream(_Delegating):
    """The same for ``await client.chat.completions.create(..., stream=True)`` on an
    ``AsyncOpenAI`` client."""

    raw: Any
    masker: Masker

    async def __aenter__(self) -> AsyncOpenAIVeilStream:
        if hasattr(self.raw, "__aenter__"):
            await self.raw.__aenter__()
        return self

    async def __aexit__(self, *exc_info: object) -> Any:
        if hasattr(self.raw, "__aexit__"):
            return await self.raw.__aexit__(*exc_info)
        return None

    async def __aiter__(self) -> AsyncIterator[Any]:
        chunks = ChunkRestorer(self.masker)
        async for chunk in self.raw:
            for restored in chunks.feed(chunk):
                yield restored
        for restored in chunks.finish():
            yield restored


def _is_async_client(client: Any) -> bool:
    """True for a client whose ``chat.completions.create`` has to be awaited."""
    completions = getattr(getattr(client, "chat", None), "completions", None)
    return needs_await(getattr(completions, "create", None))


def _response_kwargs(
    masker: Masker, replay: ReplayCache, input: Any, instructions: Any, kwargs: dict[str, Any]
) -> dict[str, Any]:
    call_kwargs = dict(kwargs)
    call_kwargs["input"] = openai_responses.mask_responses_input(input, masker, replay)
    if isinstance(instructions, str):
        call_kwargs["instructions"] = masker.mask(instructions)
    elif instructions is not None:
        call_kwargs["instructions"] = instructions
    return call_kwargs


@dataclass
class OpenAIVeil:
    """Mask-and-restore wrapper around an ``openai.OpenAI`` client.

    Example::

        from openai import OpenAI
        from veil.integrations.openai import OpenAIVeil

        veil_client = OpenAIVeil(OpenAI())
        response = veil_client.create(  # Chat Completions
            model="gpt-6-sol",
            messages=[{"role": "user", "content": "Email alice@example.com"}],
        )
        response = veil_client.create_response(  # Responses API
            model="gpt-6-sol",
            input="Email alice@example.com",
        )
    """

    client: Any
    masker: Masker = field(default_factory=Masker)
    replay: ReplayCache = field(default_factory=ReplayCache)

    def __post_init__(self) -> None:
        if _is_async_client(self.client):
            raise TypeError(
                "OpenAIVeil wraps a synchronous client (openai.OpenAI); "
                "use AsyncOpenAIVeil for openai.AsyncOpenAI"
            )

    def create(self, *, messages: list[Any], **kwargs: Any) -> Any:
        """``client.chat.completions.create``: a restored completion, or with
        ``stream=True`` an :class:`OpenAIVeilStream` of restored chunks."""
        masked = mask_messages(messages, self.masker, self.replay)
        response = self.client.chat.completions.create(messages=masked, **kwargs)
        if kwargs.get("stream"):
            return OpenAIVeilStream(response, self.masker)
        return restore_response(response, self.masker, self.replay)

    def stream(self, *, messages: list[Any], **kwargs: Any) -> OpenAIVeilStream:
        kwargs.pop("stream", None)
        masked = mask_messages(messages, self.masker, self.replay)
        raw = self.client.chat.completions.create(messages=masked, stream=True, **kwargs)
        return OpenAIVeilStream(raw, self.masker)

    def create_response(self, *, input: Any, instructions: Any = None, **kwargs: Any) -> Any:
        """``client.responses.create`` with ``input`` and ``instructions`` masked
        and the response's ``output`` restored (see :mod:`veil.integrations.openai_responses`).
        With ``stream=True``, an :class:`~veil.integrations.openai_responses.OpenAIResponsesStream`."""
        call_kwargs = _response_kwargs(self.masker, self.replay, input, instructions, kwargs)
        response = self.client.responses.create(**call_kwargs)
        if call_kwargs.get("stream"):
            return openai_responses.OpenAIResponsesStream(response, self.masker, self.replay)
        return openai_responses.restore_response(response, self.masker, self.replay)

    def stream_response(
        self, *, input: Any, instructions: Any = None, **kwargs: Any
    ) -> openai_responses.OpenAIResponsesStream:
        """``client.responses.create(..., stream=True)``, yielding restored events."""
        kwargs.pop("stream", None)
        call_kwargs = _response_kwargs(self.masker, self.replay, input, instructions, kwargs)
        raw = self.client.responses.create(stream=True, **call_kwargs)
        return openai_responses.OpenAIResponsesStream(raw, self.masker, self.replay)


